  1	import java.util.Arrays;
  2	import java.util.Objects;
  3	
  4	public final class BucketSort {
  5	
  6	    private static final float MIN_SUPPORTED_VALUE = 0.0f;
  7	    private static final float MAX_SUPPORTED_VALUE = 1.0f;
  8	
  9	    private BucketSort() {
 10	    }
 11	
 12	    public static void sort(float[] values) {
 13	        Objects.requireNonNull(values, "values");
 14	        sortInPlace(values);
 15	    }
 16	
 17	    public static float[] sortedCopy(float[] values) {
 18	        Objects.requireNonNull(values, "values");
 19	
 20	        float[] copy = Arrays.copyOf(values, values.length);
 21	        sortInPlace(copy);
 22	        return copy;
 23	    }
 24	
 25	    private static void sortInPlace(float[] values) {
 26	        if (values.length == 0) {
 27	            return;
 28	        }
 29	
 30	        int[] bucketSizes = countValuesPerBucket(values);
 31	        float[][] buckets = createBuckets(bucketSizes);
 32	        distribute(values, buckets);
 33	        sortBuckets(buckets, bucketSizes);
 34	        mergeBuckets(buckets, bucketSizes, values);
 35	    }
 36	
 37	    private static int[] countValuesPerBucket(float[] values) {
 38	        int[] bucketSizes = new int[values.length];
 39	
 40	        for (float value : values) {
 41	            validateValue(value);
 42	            bucketSizes[bucketIndexFor(value, bucketSizes.length)]++;
 43	        }
 44	
 45	        return bucketSizes;
 46	    }
 47	
 48	    private static float[][] createBuckets(int[] bucketSizes) {
 49	        float[][] buckets = new float[bucketSizes.length][];
 50	        for (int i = 0; i < bucketSizes.length; i++) {
 51	            buckets[i] = new float[bucketSizes[i]];
 52	        }
 53	        return buckets;
 54	    }
 55	
 56	    private static void distribute(float[] values, float[][] buckets) {
 57	        int[] insertionIndexes = new int[buckets.length];
 58	        for (float value : values) {
 59	            int bucketIndex = bucketIndexFor(value, buckets.length);
 60	            buckets[bucketIndex][insertionIndexes[bucketIndex]++] = value;
 61	        }
 62	    }
 63	
 64	    private static void sortBuckets(float[][] buckets, int[] bucketSizes) {
 65	        for (int i = 0; i < buckets.length; i++) {
 66	            insertionSort(buckets[i], bucketSizes[i]);
 67	        }
 68	    }
 69	
 70	    private static void mergeBuckets(float[][] buckets, int[] bucketSizes, float[] target) {
 71	        int targetIndex = 0;
 72	        for (int i = 0; i < buckets.length; i++) {
 73	            int bucketSize = bucketSizes[i];
 74	            System.arraycopy(buckets[i], 0, target, targetIndex, bucketSize);
 75	            targetIndex += bucketSize;
 76	        }
 77	    }
 78	
 79	    private static void insertionSort(float[] bucket, int size) {
 80	        for (int i = 1; i < size; i++) {
 81	            float currentValue = bucket[i];
 82	            int j = i - 1;
 83	            while (j >= 0 && bucket[j] > currentValue) {
 84	                bucket[j + 1] = bucket[j];
 85	                j--;
 86	            }
 87	            bucket[j + 1] = currentValue;
 88	        }
 89	    }
 90	
 91	    private static int bucketIndexFor(float value, int bucketCount) {
 92	        return (int) (bucketCount * value);
 93	    }
 94	
 95	    private static void validateValue(float value) {
 96	        if (!isSupportedValue(value)) {
 97	            throw new IllegalArgumentException(
 98	                "Bucket sort expects values in the range ["
 99	                    + MIN_SUPPORTED_VALUE
100	                    + ", "
101	                    + MAX_SUPPORTED_VALUE
102	                    + "): "
103	                    + value
104	            );
105	        }
106	    }
107	
108	    private static boolean isSupportedValue(float value) {
109	        return Float.isFinite(value)
110	            && value >= MIN_SUPPORTED_VALUE
111	            && value < MAX_SUPPORTED_VALUE;
112	    }
113	}

