  3	public final class BucketSortTest {
  4	
  5	    private BucketSortTest() {
  6	    }
  7	
  8	    public static void main(String[] args) {
  9	        sortsValuesInPlace();
 10	        returnsSortedCopyWithoutMutatingInput();
 11	        returnsDistinctArrayForSortedCopy();
 12	        sortsDuplicateValues();
 13	        sortsValuesAtLowerBound();
 14	        sortsValuesNearUpperBound();
 15	        rejectsUnsupportedValues();
 16	        rejectsNullInput();
 17	        handlesEmptyInput();
 18	        returnsEmptySortedCopy();
 19	    }
 20	
 21	    private static void sortsValuesInPlace() {
 22	        assertSortsInPlace(
 23	            new float[]{0.42f, 0.32f, 0.23f, 0.52f, 0.25f, 0.47f},
 24	            new float[]{0.23f, 0.25f, 0.32f, 0.42f, 0.47f, 0.52f},
 25	            "sort should order values in place"
 26	        );
 27	    }
 28	
 29	    private static void returnsSortedCopyWithoutMutatingInput() {
 30	        assertSortedCopy(
 31	            new float[]{0.78f, 0.17f, 0.39f},
 32	            new float[]{0.17f, 0.39f, 0.78f},
 33	            "sortedCopy should not mutate the source array"
 34	        );
 35	    }
 36	
 37	    private static void returnsDistinctArrayForSortedCopy() {
 38	        float[] original = {0.31f, 0.21f};
 39	        float[] copy = BucketSort.sortedCopy(original);
 40	
 41	        if (copy == original) {
 42	            throw new AssertionError("sortedCopy should return a distinct array instance");
 43	        }
 44	    }
 45	
 46	    private static void sortsDuplicateValues() {
 47	        assertSortsInPlace(
 48	            new float[]{0.41f, 0.12f, 0.41f, 0.12f, 0.73f},
 49	            new float[]{0.12f, 0.12f, 0.41f, 0.41f, 0.73f},
 50	            "sort should handle duplicate values"
 51	        );
 52	    }
 53	
 54	    private static void sortsValuesAtLowerBound() {
 55	        assertSortsInPlace(
 56	            new float[]{0.25f, 0.0f, 0.75f},
 57	            new float[]{0.0f, 0.25f, 0.75f},
 58	            "sort should support the lower bound"
 59	        );
 60	    }
 61	
 62	    private static void sortsValuesNearUpperBound() {
 63	        assertSortsInPlace(
 64	            new float[]{0.9999f, 0.0001f, 0.5f},
 65	            new float[]{0.0001f, 0.5f, 0.9999f},
 66	            "sort should support values close to the upper bound"
 67	        );
 68	    }
 69	
 70	    private static void rejectsUnsupportedValues() {
 71	        assertRejectsUnsupportedValue(1.0f, "sort should reject values outside [0.0, 1.0)");
 72	        assertRejectsUnsupportedValue(-0.01f, "sort should reject negative values");
 73	        assertRejectsUnsupportedValue(Float.NaN, "sort should reject NaN");
 74	        assertRejectsUnsupportedValue(Float.POSITIVE_INFINITY, "sort should reject infinity");
 75	    }
 76	
 77	    private static void rejectsNullInput() {
 78	        assertThrows(
 79	            NullPointerException.class,
 80	            () -> BucketSort.sort(null),
 81	            "sort should reject null input"
 82	        );
 83	    }
 84	
 85	    private static void handlesEmptyInput() {
 86	        float[] values = {};
 87	        BucketSort.sort(values);
 88	        assertArrayEquals(new float[]{}, values, "sort should leave empty input unchanged");
 89	    }
 90	
 91	    private static void returnsEmptySortedCopy() {
 92	        float[] copy = BucketSort.sortedCopy(new float[]{});
 93	        assertArrayEquals(new float[]{}, copy, "sortedCopy should handle empty input");
 94	    }
 95	
 96	    private static void assertSortsInPlace(float[] input, float[] expected, String message) {
 97	        BucketSort.sort(input);
 98	        assertArrayEquals(expected, input, message);
 99	    }
100	
101	    private static void assertSortedCopy(float[] input, float[] expected, String message) {
102	        float[] original = Arrays.copyOf(input, input.length);
103	        float[] copy = BucketSort.sortedCopy(input);
104	
105	        assertArrayEquals(original, input, message);
106	        assertArrayEquals(expected, copy, "sortedCopy should return sorted data");
107	    }
108	
109	    private static void assertRejectsUnsupportedValue(float value, String message) {
110	        assertThrows(
111	            IllegalArgumentException.class,
112	            () -> BucketSort.sort(new float[]{0.5f, value}),
113	            message
114	        );
115	    }
116	
117	    private static void assertArrayEquals(float[] expected, float[] actual, String message) {
118	        if (!Arrays.equals(expected, actual)) {
119	            throw new AssertionError(
120	                message
121	                    + ". Expected "
122	                    + Arrays.toString(expected)
123	                    + " but was "
124	                    + Arrays.toString(actual)
125	            );
126	        }
127	    }
128	
129	    private static void assertThrows(
130	        Class<? extends Throwable> expectedType,
131	        ThrowingRunnable runnable,
132	        String message
133	    ) {
134	        try {
135	            runnable.run();
136	        } catch (Throwable error) {
137	            if (expectedType.isInstance(error)) {
138	                return;
139	            }
140	            throw new AssertionError(
141	                message + ". Expected " + expectedType.getSimpleName() + " but caught " + error,
142	                error
143	            );
144	        }
145	
146	        throw new AssertionError(
147	            message + ". Expected " + expectedType.getSimpleName() + " but nothing was thrown"
148	        );
149	    }
150	
151	    @FunctionalInterface
152	    private interface ThrowingRunnable {
153	        void run();
154	    }
155	}

  1	import java.util.Arrays;
  2	import java.util.Objects;
  3	
  4	public final class BucketSort {
  5	
  6	    private static final float MIN_SUPPORTED_VALUE = 0.0f;
  7	    private static final float MAX_SUPPORTED_VALUE = 1.0f;
  8	
  9	    private BucketSort() {
 10	    }
 11	
 12	    public static void sort(float[] values) {
 13	        Objects.requireNonNull(values, "values");
 14	        sortInPlace(values);
 15	    }
 16	
 17	    public static float[] sortedCopy(float[] values) {
 18	        Objects.requireNonNull(values, "values");
 19	
 20	        float[] copy = Arrays.copyOf(values, values.length);
 21	        sortInPlace(copy);
 22	        return copy;
 23	    }
 24	
 25	    private static void sortInPlace(float[] values) {
 26	        if (values.length == 0) {
 27	            return;
 28	        }
 29	
 30	        BucketLayout bucketLayout = BucketLayout.from(values);
 31	        float[] bucketedValues = distribute(values, bucketLayout);
 32	        sortBuckets(bucketedValues, bucketLayout);
 33	        System.arraycopy(bucketedValues, 0, values, 0, values.length);
 34	    }
 35	
 36	    private static float[] distribute(float[] values, BucketLayout bucketLayout) {
 37	        float[] bucketedValues = new float[values.length];
 38	        int[] insertionIndexes = Arrays.copyOf(bucketLayout.bucketStarts, bucketLayout.bucketStarts.length);
 39	        for (float value : values) {
 40	            int bucketIndex = bucketIndexFor(value, bucketLayout.bucketCount());
 41	            bucketedValues[insertionIndexes[bucketIndex]++] = value;
 42	        }
 43	        return bucketedValues;
 44	    }
 45	
 46	    private static void sortBuckets(float[] bucketedValues, BucketLayout bucketLayout) {
 47	        for (int i = 0; i < bucketLayout.bucketCount(); i++) {
 48	            insertionSort(bucketedValues, bucketLayout.bucketStart(i), bucketLayout.bucketEnd(i));
 49	        }
 50	    }
 51	
 52	    private static void insertionSort(float[] values, int startInclusive, int endExclusive) {
 53	        for (int i = startInclusive + 1; i < endExclusive; i++) {
 54	            float currentValue = values[i];
 55	            int j = i - 1;
 56	            while (j >= startInclusive && values[j] > currentValue) {
 57	                values[j + 1] = values[j];
 58	                j--;
 59	            }
 60	            values[j + 1] = currentValue;
 61	        }
 62	    }
 63	
 64	    private static int bucketIndexFor(float value, int bucketCount) {
 65	        return (int) (bucketCount * value);
 66	    }
 67	
 68	    private static void validateValue(float value) {
 69	        if (!isSupportedValue(value)) {
 70	            throw new IllegalArgumentException(
 71	                "Bucket sort expects values in the range ["
 72	                    + MIN_SUPPORTED_VALUE
 73	                    + ", "
 74	                    + MAX_SUPPORTED_VALUE
 75	                    + "): "
 76	                    + value
 77	            );
 78	        }
 79	    }
 80	
 81	    private static boolean isSupportedValue(float value) {
 82	        return Float.isFinite(value)
 83	            && value >= MIN_SUPPORTED_VALUE
 84	            && value < MAX_SUPPORTED_VALUE;
 85	    }
 86	
 87	    private static final class BucketLayout {
 88	
 89	        private final int[] bucketStarts;
 90	
 91	        private BucketLayout(int[] bucketStarts) {
 92	            this.bucketStarts = bucketStarts;
 93	        }
 94	
 95	        private static BucketLayout from(float[] values) {
 96	            int[] bucketSizes = new int[values.length];
 97	
 98	            for (float value : values) {
 99	                validateValue(value);
100	                bucketSizes[bucketIndexFor(value, bucketSizes.length)]++;
101	            }
102	
103	            int[] bucketStarts = new int[bucketSizes.length];
104	            int nextBucketStart = 0;
105	            for (int i = 0; i < bucketSizes.length; i++) {
106	                bucketStarts[i] = nextBucketStart;
107	                nextBucketStart += bucketSizes[i];
108	            }
109	
110	            return new BucketLayout(bucketStarts);
111	        }
112	
113	        private int bucketCount() {
114	            return bucketStarts.length;
115	        }
116	
117	        private int bucketStart(int bucketIndex) {
118	            return bucketStarts[bucketIndex];
119	        }
120	
121	        private int bucketEnd(int bucketIndex) {
122	            if (bucketIndex == bucketStarts.length - 1) {
123	                return bucketStarts.length == 0 ? 0 : bucketStarts[bucketIndex] + bucketSize(bucketIndex);
124	            }
125	            return bucketStarts[bucketIndex + 1];
126	        }
127	
128	        private int bucketSize(int bucketIndex) {
129	            if (bucketIndex == bucketStarts.length - 1) {
130	                return bucketStarts.length - bucketStarts[bucketIndex] + trailingBucketAdjustment();
131	            }
132	            return bucketStarts[bucketIndex + 1] - bucketStarts[bucketIndex];
133	        }
134	
135	        private int trailingBucketAdjustment() {
136	            return 0;
137	        }
138	    }
139	}
